CREATE TABLE mp4_document(id INTEGER PRIMARY KEY,schema TEXT NOT NULL);
CREATE TABLE mp4_ftyp(id INTEGER PRIMARY KEY REFERENCES mp4_document(id),major_brand TEXT NOT NULL,minor_version INTEGER NOT NULL CHECK(minor_version BETWEEN 0 AND 4294967295));
CREATE TABLE mp4_compatible_brand(id INTEGER PRIMARY KEY,ftyp_id INTEGER NOT NULL REFERENCES mp4_ftyp(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),brand TEXT NOT NULL);
CREATE TABLE mp4_movie(id INTEGER PRIMARY KEY REFERENCES mp4_document(id),creation_time TEXT NOT NULL,modification_time TEXT NOT NULL,timescale INTEGER NOT NULL CHECK(timescale BETWEEN 0 AND 4294967295),duration TEXT NOT NULL,rate INTEGER NOT NULL CHECK(rate BETWEEN -2147483648 AND 2147483647),volume INTEGER NOT NULL CHECK(volume BETWEEN -32768 AND 32767),next_track_id INTEGER NOT NULL CHECK(next_track_id BETWEEN 0 AND 4294967295),title TEXT,encoder TEXT);
CREATE TABLE mp4_movie_matrix(id INTEGER PRIMARY KEY,movie_id INTEGER NOT NULL REFERENCES mp4_movie(id),ordinal INTEGER NOT NULL CHECK(ordinal BETWEEN 0 AND 8),value INTEGER NOT NULL CHECK(value BETWEEN -2147483648 AND 2147483647));
CREATE TABLE mp4_track(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES mp4_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),track_id INTEGER NOT NULL CHECK(track_id BETWEEN 0 AND 4294967295),timescale INTEGER NOT NULL CHECK(timescale BETWEEN 0 AND 4294967295),width INTEGER NOT NULL CHECK(width BETWEEN 0 AND 4294967295),height INTEGER NOT NULL CHECK(height BETWEEN 0 AND 4294967295));
CREATE TABLE mp4_codec(id INTEGER PRIMARY KEY REFERENCES mp4_track(id),format TEXT NOT NULL CHECK(format IN('avc1','avc3','hvc1','hev1','jpeg','mjpa')),nal_length_size INTEGER NOT NULL CHECK(nal_length_size BETWEEN 0 AND 255));
CREATE TABLE mp4_avc_sps(id INTEGER PRIMARY KEY,codec_id INTEGER NOT NULL REFERENCES mp4_codec(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),data BLOB NOT NULL);
CREATE TABLE mp4_avc_pps(id INTEGER PRIMARY KEY,codec_id INTEGER NOT NULL REFERENCES mp4_codec(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),data BLOB NOT NULL);
CREATE TABLE mp4_avc_extension(id INTEGER PRIMARY KEY REFERENCES mp4_codec(id),chroma_format INTEGER NOT NULL CHECK(chroma_format BETWEEN 0 AND 255),bit_depth_luma_minus8 INTEGER NOT NULL CHECK(bit_depth_luma_minus8 BETWEEN 0 AND 255),bit_depth_chroma_minus8 INTEGER NOT NULL CHECK(bit_depth_chroma_minus8 BETWEEN 0 AND 255));
CREATE TABLE mp4_avc_sps_extension(id INTEGER PRIMARY KEY,extension_id INTEGER NOT NULL REFERENCES mp4_avc_extension(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),data BLOB NOT NULL);
CREATE TABLE mp4_hevc_config(id INTEGER PRIMARY KEY REFERENCES mp4_codec(id),general_profile_space INTEGER NOT NULL CHECK(general_profile_space BETWEEN 0 AND 255),general_tier_flag INTEGER NOT NULL CHECK(general_tier_flag IN(0,1)),general_profile_idc INTEGER NOT NULL CHECK(general_profile_idc BETWEEN 0 AND 255),general_profile_compatibility_flags INTEGER NOT NULL CHECK(general_profile_compatibility_flags BETWEEN 0 AND 4294967295),general_constraint_indicator_flags TEXT NOT NULL,general_level_idc INTEGER NOT NULL CHECK(general_level_idc BETWEEN 0 AND 255),min_spatial_segmentation_idc INTEGER NOT NULL CHECK(min_spatial_segmentation_idc BETWEEN 0 AND 65535),parallelism_type INTEGER NOT NULL CHECK(parallelism_type BETWEEN 0 AND 255),chroma_format_idc INTEGER NOT NULL CHECK(chroma_format_idc BETWEEN 0 AND 255),bit_depth_luma_minus8 INTEGER NOT NULL CHECK(bit_depth_luma_minus8 BETWEEN 0 AND 255),bit_depth_chroma_minus8 INTEGER NOT NULL CHECK(bit_depth_chroma_minus8 BETWEEN 0 AND 255),avg_frame_rate INTEGER NOT NULL CHECK(avg_frame_rate BETWEEN 0 AND 65535),constant_frame_rate INTEGER NOT NULL CHECK(constant_frame_rate BETWEEN 0 AND 255),num_temporal_layers INTEGER NOT NULL CHECK(num_temporal_layers BETWEEN 0 AND 255),temporal_id_nested INTEGER NOT NULL CHECK(temporal_id_nested IN(0,1)));
CREATE TABLE mp4_hevc_array(id INTEGER PRIMARY KEY,config_id INTEGER NOT NULL REFERENCES mp4_hevc_config(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),array_completeness INTEGER NOT NULL CHECK(array_completeness IN(0,1)),nal_unit_type INTEGER NOT NULL CHECK(nal_unit_type BETWEEN 0 AND 255));
CREATE TABLE mp4_hevc_nal(id INTEGER PRIMARY KEY,array_id INTEGER NOT NULL REFERENCES mp4_hevc_array(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),data BLOB NOT NULL);
CREATE TABLE mp4_track_metadata(id INTEGER PRIMARY KEY REFERENCES mp4_track(id),creation_time TEXT NOT NULL,modification_time TEXT NOT NULL,flags INTEGER NOT NULL CHECK(flags BETWEEN 0 AND 4294967295),duration TEXT NOT NULL,layer INTEGER NOT NULL CHECK(layer BETWEEN -32768 AND 32767),alternate_group INTEGER NOT NULL CHECK(alternate_group BETWEEN -32768 AND 32767),volume INTEGER NOT NULL CHECK(volume BETWEEN -32768 AND 32767),media_duration TEXT NOT NULL,media_creation_time TEXT NOT NULL,media_modification_time TEXT NOT NULL,language TEXT NOT NULL,quality INTEGER NOT NULL CHECK(quality BETWEEN 0 AND 65535),handler_name TEXT NOT NULL);
CREATE TABLE mp4_track_matrix(id INTEGER PRIMARY KEY,metadata_id INTEGER NOT NULL REFERENCES mp4_track_metadata(id),ordinal INTEGER NOT NULL CHECK(ordinal BETWEEN 0 AND 8),value INTEGER NOT NULL CHECK(value BETWEEN -2147483648 AND 2147483647));
CREATE TABLE mp4_edit(id INTEGER PRIMARY KEY,metadata_id INTEGER NOT NULL REFERENCES mp4_track_metadata(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),segment_duration TEXT NOT NULL,media_time INTEGER NOT NULL,media_rate_integer INTEGER NOT NULL CHECK(media_rate_integer BETWEEN -32768 AND 32767),media_rate_fraction INTEGER NOT NULL CHECK(media_rate_fraction BETWEEN -32768 AND 32767));
CREATE TABLE mp4_visual_sample_entry(id INTEGER PRIMARY KEY REFERENCES mp4_track_metadata(id),data_reference_index INTEGER NOT NULL CHECK(data_reference_index BETWEEN 0 AND 65535),version INTEGER NOT NULL CHECK(version BETWEEN 0 AND 65535),revision_level INTEGER NOT NULL CHECK(revision_level BETWEEN 0 AND 65535),vendor INTEGER NOT NULL CHECK(vendor BETWEEN 0 AND 4294967295),temporal_quality INTEGER NOT NULL CHECK(temporal_quality BETWEEN 0 AND 4294967295),spatial_quality INTEGER NOT NULL CHECK(spatial_quality BETWEEN 0 AND 4294967295),horizontal_resolution INTEGER NOT NULL CHECK(horizontal_resolution BETWEEN 0 AND 4294967295),vertical_resolution INTEGER NOT NULL CHECK(vertical_resolution BETWEEN 0 AND 4294967295),frame_count INTEGER NOT NULL CHECK(frame_count BETWEEN 0 AND 65535),compressor_name TEXT NOT NULL,depth INTEGER NOT NULL CHECK(depth BETWEEN 0 AND 65535),color_table_id INTEGER NOT NULL CHECK(color_table_id BETWEEN -32768 AND 32767));
CREATE TABLE mp4_color(id INTEGER PRIMARY KEY REFERENCES mp4_track_metadata(id),color_type TEXT NOT NULL,primaries INTEGER NOT NULL CHECK(primaries BETWEEN 0 AND 65535),transfer INTEGER NOT NULL CHECK(transfer BETWEEN 0 AND 65535),matrix INTEGER NOT NULL CHECK(matrix BETWEEN 0 AND 65535),full_range INTEGER CHECK(full_range IN(0,1)));
CREATE TABLE mp4_pixel_aspect_ratio(id INTEGER PRIMARY KEY REFERENCES mp4_track_metadata(id),horizontal_spacing INTEGER NOT NULL CHECK(horizontal_spacing BETWEEN 0 AND 4294967295),vertical_spacing INTEGER NOT NULL CHECK(vertical_spacing BETWEEN 0 AND 4294967295));
CREATE TABLE mp4_bitrate(id INTEGER PRIMARY KEY REFERENCES mp4_track_metadata(id),buffer_size INTEGER NOT NULL CHECK(buffer_size BETWEEN 0 AND 4294967295),maximum INTEGER NOT NULL CHECK(maximum BETWEEN 0 AND 4294967295),average INTEGER NOT NULL CHECK(average BETWEEN 0 AND 4294967295));
CREATE TABLE mp4_chunk_sample_count(id INTEGER PRIMARY KEY,track_id INTEGER NOT NULL REFERENCES mp4_track(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),count INTEGER NOT NULL CHECK(count BETWEEN 0 AND 4294967295));
CREATE TABLE mp4_sample(id INTEGER PRIMARY KEY,track_id INTEGER NOT NULL REFERENCES mp4_track(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),data BLOB NOT NULL,duration INTEGER NOT NULL CHECK(duration BETWEEN 0 AND 4294967295),cts_offset INTEGER NOT NULL CHECK(cts_offset BETWEEN -2147483648 AND 2147483647),sync INTEGER NOT NULL CHECK(sync IN(0,1)));
